"""Developer-only: freeze the SDK's opcode tables and a decode parity digest."""
import ast
import hashlib
from pathlib import Path
import sys

root = Path(__file__).resolve().parents[3]
sdk = root / 'ps3recomp/tools'
module = ast.parse((sdk / 'spu_disasm.py').read_text(encoding='utf-8'))
names = dict(RRR_TABLE='RRR', RI18_TABLE='RI18', RI16_TABLE='RI16', RI10_TABLE='RI10',
             SPU_RR='RR', CHANNEL_NAMES='Channels', ri8_table='RI8',
             ri7_table='RI7', lsx_table='Indexed')
tables = {}
for node in ast.walk(module):
    if isinstance(node, ast.AnnAssign):
        target = node.target
    elif isinstance(node, ast.Assign) and len(node.targets) == 1:
        target = node.targets[0]
    else:
        continue
    if isinstance(target, ast.Name) and target.id in names and isinstance(node.value, ast.Dict):
        tables[target.id] = ast.literal_eval(node.value)
assert tables.keys() == names.keys()
lines = ['// Opcode data from the MIT-licensed PS3Recomp SDK, tools/spu_disasm.py.',
         '// Generated by the developer-only import_spu_tables.py. No Python at build/runtime.']
for key, label in names.items():
    lines += [f'constexpr Op {label}[] = {{']
    lines += [f'    {{0x{opcode:X}, "{name}"}},' for opcode, name in sorted(tables[key].items())]
    lines += ['};']
(root / 'preparation/src/spu_opcodes.inc').write_text('\n'.join(lines) + '\n', encoding='utf-8')

sys.path.insert(0, str(sdk))
from spu_disasm import spu_decode

state = 0x51c0dec0
def word():
    global state
    state ^= (state << 13) & 0xffffffff
    state ^= state >> 17
    state ^= (state << 5) & 0xffffffff
    return state

digest = hashlib.sha256()
for op in range(2048):
    for _ in range(8):
        raw = (op << 21) | (word() & 0x1fffff)
        address = word() & 0x3fffc
        decoded = spu_decode(raw, address)
        digest.update(f'{raw:08X}:{address:08X}:{decoded.mnemonic}:{decoded.operands}\n'.encode())
(Path(__file__).parent / 'spu-decode.sha256').write_text(digest.hexdigest() + '\n', encoding='ascii')
